package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamKandyTradBank3 {
    private const val T = "මහනුවර යුගයේ සිතුවම්, දේශීය ශෛලිය හා වාස්තු කැටයම්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("මහනුවර ශ්‍රී දළදා මාලිගාවේ අෂ්ටාස්‍රාකාර පත්තිරිප්පුව නිර්මාණය කළ ප්‍රධාන වාස්තු ශිල්පියා කවුරුන්ද?", "දේවේන්ද්‍ර මූලාචාරියා", "දෙල්මඩ මූලාචාරියා", "දෙවරගම්පල සිල්වත්තැන", "නීලගම පටබැඳි ශිල්පියා", "ශ්‍රී වික්‍රම රාජසිංහ රජුගේ කාලයේදී දේවේන්ද්‍ර මූලාචාරියා විසින් අලංකාර පත්තිරිප්පුව නිමවන ලදී."),
        q("ශ්‍රී දළදා මාලිගාවේ දිය අගල අද්දර පිහිටි සුදු පැහැති සාම්ප්‍රදායික පවුර හඳුන්වන්නේ කුමන නමින්ද?", "වළාකුළු බැම්ම හා දියරැලි බැම්ම", "පලාපෙති බැම්ම හා ගජසිංහ බැම්ම", "නාරිලතා බැම්ම හා බෝපත් බැම්ම", "කිරිගරුඬ බැම්ම හා මකර බැම්ම", "මහනුවර නගර සැලසුමේදී දියරැලි මෝස්තරයෙන් යුත් වළාකුළු බැම්ම ඉතා සුවිශේෂී කලා අංගයකි."),
        q("මහනුවර යුගයේ 'ටැම්පිට විහාර' ගල් කුළුණු මත උස්ව ඉදි කිරීමෙන් ශිල්පියා අපේක්ෂා කළ ප්‍රධාන ප්‍රායෝගික අරමුණ කුමක්ද?", "වේයන්ගෙන් හා තෙතමනයෙන් බිත්ති රැක ගැනීම", "සතුරු හමුදාවලින් රජු සැඟවී සිටීම", "ගුවනින් යන දෙවියන්ට පූජාසන තැනීම", "පොළොව යට ධාතු නිධන් ගබඩා කිරීම", "මැටි වරිච්චි බිත්ති හා දැව කොටස් වේයන්ගෙන් හා ගංවතුරෙන් ආරක්ෂා කිරීමට ටැම්පිට ක්‍රමය යොදන ලදී."),
        q("මහනුවර යුගයේ විශිෂ්ට දැව කැටයම් සහිත දෙමහල් 'පේකඩ' (Wooden Brackets) බහුලව භාවිත කළේ කුමන අංගයටද?", "කුළුණු හිස් මත වහලයේ බාල්ක දරා සිටීමට", "විහාර දොරටු ඉදිරිපස සඳකඩපහණ තැනීමට", "බිතුසිතුවම් අඳින කපරාරු බදාමය සැකසීමට", "දිය අගල මතින් පාලම් ඉදිකිරීමට", "ඇම්බැක්කේ දේවාලයේ හා මඟුල් මඩුවේ නෙළුම් මල් පෙති මෝස්තර සහිත පේකඩ ඉතා අලංකාර වේ."),
        q("මහනුවර මඟුල් මඩුවේ (Audience Hall) කැටයම් කර ඇති විශාල දැව කුළුණු සඳහා යොදාගත් ප්‍රධාන දැව වර්ගය කුමක්ද?", "හල්මිල්ල හා නා ලී දැව", "වෙල්කදුරු හා රුක් අත්තන දැව", "හුණුගල් හා කළුගල් කුට්ටි", "උණ බට හා පොල් කඳන් දැව", "ශක්තිමත් බව හා සියුම් කැටයමට ඔරොත්තු දීම නිසා හල්මිල්ල හා නා ලී කැටයම් සඳහා තෝරා ගැණිනි."),
        q("ශ්‍රී ලාංකේය සාම්ප්‍රදායික කලා ශිල්පියෙකුගේ දක්ෂතාව මැනීමේ අවසාන ප්‍රායෝගික පරීක්ෂණය ලෙස සැලකුණු නිර්මාණය කුමක්ද?", "තිරිඟි තලේ (Tiringi Tale)", "හංස පූට්ටුව (Hansa Puttuwa)", "පංචනාරි ඝටය (Panchanari Ghata)", "සප්තනාරි තුරඟා (Saptanari Turanga)", "කෙසෙල් කොළයක හෝ ගල් ලෑල්ලක නොකඩවා රිද්මයානුකූලව අඳින ලද තිරිඟි තලේ ශිල්පියාගේ රේඛා පාලනය මනින ලදී."),
        q("සාම්ප්‍රදායික උඩරට මෝස්තර කලාවේ 'ලියවැල' සහ 'සපුෂ්පිත ලියවැල' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "සපුෂ්පිත ලියවැලේ මල් හා පොහොට්ටු පිපී තිබීම", "සපුෂ්පිත ලියවැලේ සිංහ හිස් පමණක් තිබීම", "ලියවැල යනු සෘජු රේඛා කොටු රටාවක් වීම", "සපුෂ්පිත ලියවැල කළු-සුදු වර්ණයෙන් පමණක් තිබීම", "වක්‍ර ලතා රේඛා අතර අලංකාර පිපුණු මල් යෙදූ විට එය සපුෂ්පිත ලියවැල ලෙස හඳුන්වයි."),
        q("කාන්තා රූප පහක් එකට බැඳී පුන්කලසක හැඩය මවන සාම්ප්‍රදායික මහනුවර මෝස්තරය හඳුන්වන්නේ කෙසේද?", "පංචනාරි ඝටය (Panchanari Ghata)", "සප්තනාරි තුරඟා (Saptanari Turanga)", "නවනාරි කුංජරය (Navanari Kunjara)", "චතුර්නාරි පල්ලැක්කිය (Chaturnari Pallakkiya)", "ඇම්බැක්කේ කැටයම් හා දළදා මාලිගාවේ ඇත්දත් කැටයම් අතර මෙම පංචනාරි ඝට මෝස්තරය ජනප්‍රිය විය."),
        q("කාන්තා රූප හතක් එකට එකතු වී අශ්වයෙකුගේ හැඩය මවන උඩරට සාම්ප්‍රදායික මෝස්තරය කුමක්ද?", "සප්තනාරි තුරඟා", "නවනාරි කුංජරය", "පංචනාරි ඝටය", "අෂ්ටනාරි රථය", "මිනිස් රූප ශෛලිගත කරමින් සංයුති කලාපය තුළ අශ්ව රුවක් මැවීම උඩරට ශිල්පියාගේ නිර්මාණශීලීත්වය පෙන්වයි."),
        q("කාන්තා රූප නවයක් එකිනෙකට බැඳී ඇතෙකුගේ හැඩය නිර්මාණය කරන මෝස්තරය කුමක්ද?", "නවනාරි කුංජරය", "පංචනාරි ඝටය", "සප්තනාරි තුරඟා", "හංස පූට්ටුව", "ශෘංගාරාත්මක නර්තන ඉරියව් මගින් මුළු හැඩය ඇතෙකුගේ ආකෘතියට සකසා ඇති මෝස්තරයකි."),
        q("මහනුවර යුගයේ සාම්ප්‍රදායික මල් මෝස්තර අතර 'පලාපෙති' මෝස්තරය ප්‍රධාන වශයෙන් යොදාගන්නේ කුමන ස්ථාන සඳහාද?", "වාටි හා තීරු අලංකරණ සීමා රේඛා සඳහා", "විහාර බිතුසිතුවම්වල මැද ප්‍රධාන රූපයට", "ලී පේකඩවල ඇතුළත සිදුරු පිරවීමට", "දේවාල වහලයේ මැටි උළු මත පමණක්", "නෙළුම් මල් පෙති ශෛලිගත කරමින් නිමැවුණු පලාපෙති රටාව සෑම උඩරට මෝස්තර රාමුවකම පාහේ දක්නට ලැබේ."),
        q("පාරම්පරික මෝස්තර කලාවේ 'මල සහ සත්ව රූප' අතර පෙනෙන 'සේරපෙන්ඩියා' යනු කුමන ආකාරයේ කල්පිත සත්වයෙක්ද?", "සිංහ සිරුර හා කුරුලු හිසක් ඇති සත්වයෙකි", "ඇත් හිස හා මත්ස්‍ය වලිගයක් ඇති සත්වයෙකි", "හිස් දෙකක් ඇති රාජාලි පක්ෂියෙකි", "ගව හිස හා මිනිස් සිරුරක් ඇති සත්වයෙකි", "උළුවහු, වාහල්කඩ හා රන් ආභරණ අලංකරණයේදී ආරක්ෂක සංකේතයක් ලෙස සේරපෙන්ඩියා බහුලව යෙදේ."),
        q("කැටයම් හා බිතුසිතුවම්වල අතිරේක අවකාශය පිරවීමට යොදන කුඩා තිත් හා බිංදු රටා දෙක මොනවාද?", "අරිම්බුව සහ ගල්බිංදුව", "හංස පූට්ටුව සහ මකරා", "ලියවැල සහ පලාපෙති", "කිඳුරා සහ භේරුණ්ඩයා", "වටිනා මැණික් හා රන් කැට සිහිගන්වන අරිම්බුව හා ගල්බිංදුව මෝස්තර පටිවල අලංකාරය වැඩි කරයි."),
        q("මහනුවර යුගයේ චිත්‍ර ශිල්පයේදී 'පහළ රට හෙවත් දක්ෂිණ සම්ප්‍රදායේ' විහාර සිතුවම් හා උඩරට සිතුවම් වෙනස් වන්නේ කෙසේද?", "පහතරට සිතුවම්වල බටහිර ඇඳුම් හා තානය පෙනීම", "පහතරට සිතුවම් තනි කළු රේඛාවට සීමා වීම", "උඩරට සිතුවම් කැන්වස් රෙද්දේ පමණක් ඇඳීම", "පහතරට සිතුවම්වල ජාතක කතා නොඇඳීම", "කතලුව, මුල්කිරිගල හා කරගම්පිටිය වැනි දකුණු විහාරවල 19 වන සියවසේ යුරෝපීය ආභාසය මුසු වී ඇත."),
        q("දඹුල්ල රජමහා විහාරයේ ලෙන් අංක 2 හෙවත් 'මහාරාජ විහාරයේ' සිවිලිමේ ඇඳ ඇති සුප්‍රකට බුදු සිරිත සිතුවම කුමක්ද?", "මාර පරාජය හා සත්සතිය සිතුවම්", "පන්සිය පනස් ජාතක පොතේ සම්පූර්ණ කතා", "මහාවංශයේ සියලුම රජවරුන්ගේ රුව", "අම්බලන්ගොඩ කෝලම් නැටුම් පෙළපාලිය", "ගලේ ස්වභාවික රැලි මත රෙදි වියනක් සේ බුදු පිළිම සිය ගණනක් හා මාර යුද්ධය දඹුල්ලේ ඇඳ ඇත."),
        q("මහනුවර යුගයේ විහාර සිතුවම්වල 'බිතුසිතුවම් තීරු' (Registers) අතර කතා පුවත කියවීමේ පහසුවට යොදාගත් ක්‍රමය කුමක්ද?", "පැරණි සිංහල අකුරින් හැඳින්වීමේ පාඨ ලිවීම", "වීඩියෝ අංක හා ඊතල රතු පාටින් ඇඳීම", "රූප අතර පාලම් හා මහාමාර්ග ඇඳීම", "එක් ජාතක කතාවකට එක් රූපයක් පමණක් ඇඳීම", "සෑම සිතුවම් කොටුවක් යටම තිරස් තීරුවක කතා පුවතේ අවස්ථාව සිංහලෙන් ලියා දැක්වීම සම්ප්‍රදාය විය."),
        q("මහනුවර යුගයේ සිතුවම් ශිල්පියා තම කලා කෘතිවල 'මානව රූපවල ඇස්' ඇඳීමේදී භාවිත කළ සුවිශේෂී රීතිය කුමක්ද?", "පැතිකඩ මුහුණේ පවා ඇස ඉදිරිපසින් සම්පූර්ණව ඇඳීම", "සියලු මිනිසුන්ගේ ඇස් වසා සිටින සේ ඇඳීම", "ඇස වෙනුවට කුඩා කළු තිතක් පමණක් තැබීම", "පසුබිමේ වර්ණයෙන්ම ඇස් මකා දැමීම", "මිසර සිතුවම්වල මෙන් පැතිකඩ හිසක ඉදිරිපස ඇසක් ඇඳීම මහනුවර ජනප්‍රිය සිතුවම් රීතියකි."),
        q("මහනුවර යුගයේ බිතුසිතුවම් ඇඳීමේදී 'තීන්ත වර්ණක' දියරයට මුසු කළ ස්වාභාවික මැලියම් (Binder) ද්‍රව්‍ය මොනවාද?", "දිවුල් ලාටු, දොරණ තෙල් හා කජු ලාටු", "පැරෆින් ඉටි හා ටර්පන්ටයින් ද්‍රාවකය", "සත්ව ජෙලටින් හා බිත්තර සුදු මදය", "කෘත්‍රිම ප්ලාස්ටික් රෙසින් හා ඇක්‍රිලික්", "දිවුල් ලාටු වැනි ශාක මැලියම් නිසා සිතුවම් වර්ණ බදාමයට තදින් ඇලී දිගු කල් පවතී."),
        q("මහනුවර යුගයේ සිතුවම්වල 'දුෂ්ට චරිත' (උදා: ජූජක බමුණා, මාර සේනාව) හඳුනා ගැනීමට ශිල්පියා යොදාගත් දෘශ්‍ය සංකේත කුමක්ද?", "විකෘති මුහුණු, නෙරූ දත් හා කළු-අළු පැහැය", "සුදු නෙළුම් මල් හා රන්වන් පැහැති සිරුරු", "සාමකාමී ධ්‍යාන ඉරියව් හා මෘදු සිනහව", "දිව්‍යමය ඔටුනු හා සුදු පැහැති රැස් වළලු", "මහනුවර ශිල්පියා චරිත ස්වභාවය අනුව වර්ණ හා මුහුණේ විකෘති රේඛා ඉතා නිර්මාණශීලීව භාවිත කළේය."),
        q("කෑගල්ල දිස්ත්‍රික්කයේ 'සුරියගොඩ විහාරය' හා මහනුවර 'ගංගාරාම විහාරය' ප්‍රසිද්ධියට පත්ව ඇත්තේ කුමන කලා උරුමය නිසාද?", "මහනුවර යුගයේ සුරැකි බිතුසිතුවම් හා රජ පිළිම", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ නිධිය නිසා", "චෝල යුගයේ ශිව දේවාල නටබුන් නිසා", "බටහිර යථාර්ථවාදී දියසායම් සිතුවම් නිසා", "කීර්ති ශ්‍රී රාජසිංහ සමයේ ශාසන පුනර්ජීවනයත් සමඟ බිහි වූ ප්‍රධාන විහාර චිත්‍ර මෙහි දැකිය හැකිය."),
        q("මහනුවර යුගයේ 'වැලිවිට සරණංකර සංඝරාජ හිමියන්ගේ' ශාසනික මෙහෙවර චිත්‍ර කලාවට බලපෑවේ කෙසේද?", "විහාර ප්‍රතිසංස්කරණ හා සිතුවම් කලාව පිබිදීමෙන්", "සියලු විහාර සිතුවම් තහනම් කර ඉවත් කිරීමෙන්", "යුරෝපීය තෙල් සායම් ගෙන්වා බෙදා දීමෙන්", "සිංහල කැටයම් වෙනුවට ග්‍රීක මූර්ති තැනීමෙන්", "සියම් උපසම්පදාව පිහිටුවීමත් සමඟ කීර්ති ශ්‍රී රාජසිංහ රජු විහාර සිතුවම් කලාවට අනුග්‍රහය දැක්වීය."),
        q("මහනුවර යුගයේ දැව කැටයම් හා විහාර දොරටුවල 'මකර තොරණ' නිමැවීමේදී මකරාගේ මුඛයෙන් පිටතට එන සේ නෙළා ඇත්තේ කුමක්ද?", "සිංහ හෝ ගජසිංහ හා ලියවැල් රටා", "ගුවන් යානා හා බටහිර අශ්ව රථ", "වීදුරු බඳුන් හා මැටි කළ පෙළ", "කිසිවක් නොමැති හිස් හතරැස් පුවරු", "විහාර පිළිමගෙයි ප්‍රවේශය හා බුදු පිළිමය වටා ඇති මකර තොරණ ආරක්ෂාව හා රාජකීය තේජස දක්වයි."),
        q("මහනුවර යුගයේ 'බුදු පිළිම' වල දක්නට ලැබෙන 'සිරස්පත' (Flame Finial) පිළිමයේ හිස මුදුනේ නෙළා ඇත්තේ කුමන හැඩයෙන්ද?", "ගිනිසිළු පහක හෝ ඊට වැඩි කේතුමය හැඩයෙන්", "පැතලි වටකුරු හිරු තැටියක හැඩයෙන්", "කුරුලු පිහාටු තුනක කැටයම් හැඩයෙන්", "සත් පෙණ නාග ඡත්‍රයක හැඩයෙන්", "බුදුන් වහන්සේගේ ප්‍රඥාලෝකය සංකේතවත් කරන සිරස්පත මහනුවර පිළිමවල කැපී පෙනෙන ලක්ෂණයකි."),
        q("මහනුවර යුගයේ බුදු පිළිමවල සිවුරු රැලි (Robe Folds) අනුරාධපුර යුගයේ පිළිමවලට වඩා වෙනස් වන්නේ කෙසේද?", "රැලි රැලි වශයෙන් උස් වූ සමාන්තර තීරු ලෙස නෙළීම", "සිරුරේ හැඩය විනිවිද පෙනෙන සිනිඳු රෙද්දක් සේ", "කිසිදු සිවුරු රැල්ලක් නොමැතිව හිස්ව තැබීම", "පොළොන්නරු යුගයේ මෙන් ද්විත්ව ඉරි කැපීමෙන්", "තද ගැඹුරු සමාන්තර රැලි පටි මෙන් නෙළූ චීවරය මහනුවර මූර්ති ශෛලිය හඳුනා ගැනීමේ ප්‍රධාන සලකුණකි."),
        q("මහනුවර යුගයේ බුදු පිළිම වර්ණ ගැන්වීමේදී චීවරය සඳහා බහුලව යොදාගත් වර්ණය කුමක්ද?", "දීප්තිමත් කහ හෝ තැඹිලි රතු පැහැය", "තද නිල් හා කොළ පැහැති වර්ණ", "සුදු හා අළු පැහැති මිශ්‍ර තාන", "තද දම් හා කළු පැහැති සායම්", "බදාමය මත නෙළූ ප්‍රතිමා කහ-රන්වන් හා සාදිලිංගම් රතු පැහැයෙන් අලංකාර ලෙස වර්ණ ගැන්වීය."),
        q("හපුවිද හා පල්ලෙහපුවිද ප්‍රදේශ ප්‍රසිද්ධියට පත්ව ඇති උඩරට 'ලාක්ෂා කර්මාන්තයේදී' භාවිත කරන ප්‍රධාන ශිල්ප ක්‍රම දෙක මොනවාද?", "නියපොතු වැඩ හා පත්තල වැඩ", "වෙට්-ඔන්-වෙට් හා ඩ්‍රයි බ්‍රෂ්", "මධූච්ඡිෂ්ට හා ඩ්‍රයිපොයින්ට්", "ලිනෝ කැපුම් හා සිල්ක් ස්ක්‍රීන්", "කැප්පෙටියා ලාක්ෂා ඉටි රත් කර නූල් මෙන් ඇද නියපොත්තෙන් තද කිරීම (නියපොතු) හා රෝදයේ ඇල්ලීම (පත්තල) සිදු කෙරේ."),
        q("සාම්ප්‍රදායික ලාක්ෂා කර්මාන්තයේදී සැරසිලි කරන සේසත් මිටි, හැරමිටි හා පෙට්ටි සඳහා ලබා ගන්නා ප්‍රධාන වර්ණ හතර මොනවාද?", "රතු, කහ, කළු සහ කොළ වර්ණ", "නිල්, දම්, රෝස සහ අළු වර්ණ", "සුදු, තැඹිලි, රිදී සහ දුඹුරු වර්ණ", "ලා නිල්, තද දම්, රන් සහ සුදු", "සාදිලිංගම් (රතු), හිරියල් (කහ), අංජනකැට/දැලි (කළු) සහ කොළ මිශ්‍රණය ලාක්ෂා සම්ප්‍රදායේ වර්ණ වේ."),
        q("මාතලේ පල්ලෙහපුවිද ලාක්ෂා කර්මාන්තයට අවශ්‍ය 'ලාක්ෂා' (Lac Resin) ස්වභාවිකව ලබා ගන්නේ කුමන ශාකයෙන්ද?", "කැප්පෙටියා ගස්වල ලාක්ෂා කෘමියාගෙන්", "රබර් ගස්වල සුදු පැහැති කිරිවලින්", "කොස් ගස්වල ඇලෙනසුලු කොහොල්ලෑවලින්", "පොල් ගස්වල මල් රේණු හා පොලු වලින්", "කැප්පෙටියා හෝ කෝන් ගස් අතුවල වෙසෙන ලැකිෆර් ලැක්කා කෘමියා නිපදවන මැලියම් මෙයට යොදයි."),
        q("දුම්බර රටා (හෙනස්වල / තලාතුඔය) කලාත්මක පැදුරු හා බිත්ති සැරසිලි විවීමේදී භාවිත කරන ප්‍රධාන කෙඳි ද්‍රව්‍යය කුමක්ද?", "හණ ගස්වල කෙඳි (Hemp Fiber)", "සිල්ක් පණු කෝෂවල සියුම් නූල්", "වැටකෙයියා හා පන් ගස්වල පත්‍ර", "පොල් ලෙලි කොහු හා කපු නූල්", "නියඳ හා හණ පත්‍ර සූරා ලබාගත් කෙඳි ස්වභාවික වර්ණකවල පොඟවා අලංකාර ජ්‍යාමිතික රටා වියනු ලැබේ."),
        q("දුම්බර රටා නිර්මාණවල බහුලව දැකිය හැකි සාම්ප්‍රදායික සත්ව හා ජ්‍යාමිතික මෝස්තර මොනවාද?", "කුරුලු හා නෙළුම් මල් ජ්‍යාමිතික රටා", "බටහිර දුම්රිය හා මෝටර් රථ රූප", "ග්‍රීක කුළුණු හා මූර්ති ඡායාරූප", "චීන අකුරු හා ජපන් සුමි-එ චිත්‍ර", "කෙඳි විවීමේ තාක්ෂණයට ගැළපෙන සේ පියවර හා කෝණික හැඩතලවලින් කුරුල්ලන්, මල් හා මුවන් නිමවයි."),
        q("මහනුවර යුගයේ 'පිත්තල හා රිදී කැටයම්' කලාව ප්‍රචලිත වූ ප්‍රධාන ගම්මාන යුගලය කුමක්ද?", "නීලවල හා ගඩලාදෙණිය / පිළිමතලාව", "අම්බලන්ගොඩ හා තොටගමුව / හික්කඩුව", "මිහින්තලේ හා අවුකන / මැදිරිගිරිය", "තිස්සමහාරාමය හා කතරගම / වැල්ලවාය", "උඩරට පාරම්පරික කම්මල් ශිල්පීන් පහන්, කොතල, කිල්ලෝට හා හෙප්පු ඉතා සියුම්ව නිපදවූහ."),
        q("පැරණි උඩරට පිත්තල කර්මාන්තයේදී ලෝහ භාණ්ඩයක කොටා ඇති සියුම් ඉරි තුළට වෙනත් ලෝහ නූලක් (රිදී/තඹ) කාවැද්දීම කුමක්ද?", "රිදී කර්මාන්තය හෙවත් කොප්පර කැටයම් (Inlay)", "සිල්ක් ස්ක්‍රීන් මුද්‍රණ කලාව", "මධූච්ඡිෂ්ට හෙවත් ඉටි වාත්තු ක්‍රමය", "ටෙම්පරා බිතුසිතුවම් ආලේප ක්‍රමය", "පිළිමතලාව හා ගඩලාදෙණිය ශිල්පීන් භාවිත කළ මෙම දැමස්කීන් (Damascening) ක්‍රමයෙන් අලංකාර රටා මතු වේ."),
        q("මහනුවර රාජකීය පෙරහැරේ සහ විහාර සිතුවම්වල දක්නට ලැබෙන උස රිටක සවි කළ වෘත්තාකාර අලංකරණ අංගය කුමක්ද?", "සේසත (Sesatha)", "මුරගල (Guardstone)", "සඳකඩපහණ (Moonstone)", "වටදාගෙය (Vatadage)", "විවිධ වර්ණ අභ්‍රක (Mica) හා තල කොළ මත හංස පූට්ටු, පලාපෙති ආදිය අලවා සේසත් සකසයි."),
        q("මහනුවර යුගයේ 'ඇත්දත් කැටයම්' (Ivory Carving) කලා කෘති අතර ඉතා අගනා නිර්මාණ ලෙස හඳුනාගන්නා භාණ්ඩ මොනවාද?", "වටාපත් මිටි, පනා හා ධාතු කරඬු", "ගඩොල් බැමි, උළු හා ගල් කුළුණු", "ලෝකඩ සීනු හා යකඩ කඩු තල", "පිළිස්සූ මැටි කළ හා පැදුරු", "ශ්‍රී දළදා මාලිගාවේ හා කොළඹ කෞතුකාගාරයේ ඇති ඇත්දත් කැටයම් සියුම් විනිවිද පෙනෙන කැටයම් පෙන්වයි."),
        q("මහනුවර ඇත්දත් කැටයම්වල පෙනෙන ඉතා ප්‍රසිද්ධ 'කන්ද උඩරට පනා' (Ivory Combs) මත බහුලව කැටයම් කර ඇති රූප මොනවාද?", "නර්තන කාන්තා රූප හා හංස පූට්ටු", "ප්‍රාග් ඓතිහාසික බයිසන් ගව රූප", "ග්‍රීක රණශූරයන් හා අශ්ව රථ", "ඊජිප්තු හයිරොග්ලිෆික්ස් රූපාක්ෂර", "ස්ත්‍රී පනා දෙපස මැද කොටුවේ දෙව් ලියන් හෝ කිඳුරියන් සියුම්ව කැටයම් කර ඇත."),
        q("මහනුවර යුගයේ 'ලංකාතිලක' හා 'ගඩලාදෙණිය' විහාර අයත් වන්නේ කුමන සංක්‍රාන්තික යුගයක ආරම්භයටද?", "ගම්පොළ යුගයට (14 වන සියවස)", "අනුරාධපුර මුල් යුගයට (ක්‍රි.පූ. 3 සියවස)", "පොළොන්නරු මහා පරාක්‍රමබාහු යුගයට", "බ්‍රිතාන්‍ය යටත් විජිත යුගයට", "ගම්පොළ යුගයේ ඉදි වූ මෙම විහාර උඩරට කලා සම්ප්‍රදායේ පදනම ලෙස පසුකාලීන මහනුවර යුගයේදී සංවර්ධනය විය."),
        q("ගම්පොළ යුගයේ 'ගඩලාදෙණිය' රජමහා විහාරයේ ගෘහ නිර්මාණ ශෛලිය කෙරෙහි බලපෑ ප්‍රධාන විදේශීය ආභාසය කුමක්ද?", "දකුණු ඉන්දීය විජයනගර හා ද්‍රවිඩ ශෛලිය", "යුරෝපීය ගොතික් හා බැරොක් ශෛලිය", "චීන ටැං රාජවංශ ලී වාස්තු ශෛලිය", "ග්‍රීක කොරින්තියානු කුළුණු ශෛලිය", "ගණේශ්වරාචාරී නමැති ඉන්දීය ශිල්පියාගේ මූලිකත්වයෙන් කළුගලින් මෙම දේවාල-විහාර සංකීර්ණය නිමවිණි."),
        q("ගම්පොළ යුගයේ 'ලංකාතිලක' විහාරයේ හතරැස් පියස්ස හා බාහිර බිත්ති නිරීක්ෂණය කිරීමේදී පෙනෙන ප්‍රධාන ලක්ෂණය කුමක්ද?", "බෞද්ධ පිළිමගෙය වටා හින්දු දේවාල පිහිටීම", "සම්පූර්ණයෙන්ම රවුම් වටදාගෙයක් පැවතීම", "වීදුරු හා යකඩ රාමුවලින් ඉදිකර තිබීම", "වහලයක් නොමැතිව එළිමහනේ පැවතීම", "මෙරට බෞද්ධ හා දේව ඇදහිලි එකම වාස්තු නිර්මාණයක් තුළ ඒකාබද්ධ වූ ආකාරය මෙයින් පැහැදිලි වේ."),
        q("ඇම්බැක්කේ දේවාලයේ හේවිසි මණ්ඩපයේ කැටයම් පුවරු 514ක් තුළ ප්‍රධාන කැටයම් මෝස්තර වර්ග කීයක් පමණ හඳුනාගෙන තිබේද?", "මෝස්තර වර්ග 128ක් පමණ", "මෝස්තර වර්ග 5ක් පමණ", "මෝස්තර වර්ග 1000ක් පමණ", "මෝස්තර වර්ග 12ක් පමණ", "එකම කුළුණක පවා පැති හතරේ එකිනෙකට වෙනස් දක්ෂ කැටයම් රාශියක් නෙළා ඇත."),
        q("ඇම්බැක්කේ දේවාලයේ දැව කුළුණුවල ඇති සුවිශේෂී කැටයම් අතර 'මල්ලව පොරය' හා 'නළඟන' රූප මගින් පෙන්වන්නේ කුමක්ද?", "සාමාන්‍ය ජන ජීවිතය හා විනෝදාංශ කලාව", "යුද පිටියේ විදේශ ආක්‍රමණ විස්තර", "බුද්ධ චරිතයේ දස පාරමිතා කතා", "මිසරයේ පාරාවෝ රජවරුන්ගේ ජීවිතය", "ආගමික මෝස්තරවලට අමතරව එවකට පැවති ජන ක්‍රීඩා, නැටුම් හා සත්ව චර්යා ඇම්බැක්කේ කැටයම් විය."),
        q("ඇම්බැක්කේ දේවාලයේ ප්‍රධාන පිවිසුම් දොරටුව ඉහළින් කැටයම් කර ඇති 'උසභ කුංජරය' යනු කුමන රූප සංයෝජනයක්ද?", "ගවයා සහ ඇතා යන හිස් දෙකම පෙනෙන රුවකි", "සිංහයා සහ මොනරා එක්ව සිටින රුවකි", "අශ්වයා සහ නාගයා එක්ව සිටින රුවකි", "මිනිසා සහ කිඹුලා එක්ව සිටින රුවකි", "ඇස යොමු කරන කෝණය අනුව එක් පසෙකින් ඇතෙකු ලෙසත් අනෙක් පසින් ගවයෙකු ලෙසත් පෙනෙන දෘශ්‍ය කැටයමකි."),
        q("ඇම්බැක්කේ කැටයම් අතර හමුවන 'භේරුණ්ඩ පක්ෂියා' බොහෝ විට සංකේතවත් කරන්නේ කුමන ගුණාංගයක්ද?", "අසාමාන්‍ය බලය, ශක්තිය හා ආරක්ෂාව", "ශෝකය, පරාජය හා නිහඬ භාවනාව", "කෘෂිකාර්මික අස්වැන්න හා වැස්ස", "දරුවන්ගේ කෙළිලොල් ළමා විය", "සතර කෝරළයේ කොඩියේ පවා යොදා ගැනුණු හිස් දෙකේ භේරුණ්ඩ පක්ෂියා ප්‍රෞඪත්වය නිරූපණය කරයි."),
        q("මහනුවර යුගයේ චිත්‍ර ශිල්පයේදී 'ප්‍රමාණික අනුපාත' (Hierarchical Scale) භාවිත කිරීම යනු කුමක්ද?", "වැදගත්ම චරිතය අනෙක් රූපවලට වඩා විශාල කිරීම", "සියලුම චරිත එකම මිලිමීටර ගණනට ඇඳීම", "දිගු දුර දර්ශන ඉතා කුඩා කර කොනක ඇඳීම", "පසුබිමේ ගස් පමණක් මිනිසුන්ට වඩා විශාල කිරීම", "බුදුන් වහන්සේ හෝ රජතුමා සිතුවමේ කේන්ද්‍රීය වන සේ අනෙක් රූපවලට වඩා උසින් හා විශාලව අඳියි."),
        q("මහනුවර යුගයේ බිතුසිතුවම්වල 'රතු පසුබිම' හෙවත් හිස් අවකාශය මත පුංචි මල් ඇඳ තැබීමේ උපක්‍රමය කුමක් සඳහාද?", "අවකාශ පිරවීම හා සැරසිලි සමබරතාව රැකීමට", "චිත්‍රයේ ත්‍රිමාණ ගැඹුර මැනීම සඳහා", "වර්ණ චක්‍රයේ සිසිල් බව වැඩි කිරීම සඳහා", "නරඹන්නාට කතා පුවත සඟවා තැබීම සඳහා", "සිතුවමේ මිනිස් රූප අතර ඉතිරි වන පසුබිම් ඉඩෙහි නෙළුම් මල් හෝ රන් රටා ඉස අලංකාර කරයි."),
        q("මහනුවර යුගයේ සිතුවම්වල ස්වභාවික ඛනිජ වර්ණ අතරින් 'සුදු පැහැය' සකස් කර ගත්තේ කුමන ද්‍රව්‍යයකින්ද?", "මකුළු මැටි (Kaolin Clay) මගින්", "හිරියල් හා කහ කුඩු මගින්", "සාදිලිංගම් හා ගුරුගල් මගින්", "කැප්පෙටියා කොළ යුෂ මගින්", "පිරිසිදු සුදු මකුළු මැටි සියුම්ව අඹරා හුණු බදාමය මත පසුබිමට හා රූපවලට යොදා ගැණිනි."),
        q("මහනුවර යුගයේ චිත්‍ර ශිල්පීන් 'කළු පැහැය' සහ සියුම් සමෝච්ඡ රේඛා ඇඳීමට භාවිත කළ ද්‍රව්‍යය කුමක්ද?", "හල්දුම්මල දැලි හා කපු කළු මිශ්‍රණය", "රතු සාදිලිංගම් හා ජලය මිශ්‍රණය", "රන් ආලේපිත තඹ කුඩු මිශ්‍රණය", "නිල් අවරිය කොළ තැම්බූ දියරය", "තෙල් පහන් දැලි හෝ අඟුරු හොඳින් අඹරා දිවුල් ලාටු සමඟ මිශ්‍ර කර සමෝච්ඡ රේඛා ඇඳ ඇත."),
        q("මහනුවර යුගයේ බිතුසිතුවම් ඇඳීමට ශිල්පීන් සකස් කරගත් සියුම් පින්සල් සාදා ගත්තේ කුමන ස්වභාවික ද්‍රව්‍යවලින්ද?", "වැටකෙයියා මුල් හා බළල්/ලේන් ලොම්වලින්", "කෘත්‍රිම නයිලෝන් කෙඳි හා ප්ලාස්ටික් මිටෙන්", "යකඩ කම්බි හා තඹ පතුරුවලින්", "ලී අඟුරු කැබලි හා කෙසෙල් පට්ටාවලින්", "තෙලිතුඩ ලෙස හැඳින්වුණු සියුම් පින්සල් දේශීය ලොම් හා තණ කෙඳිවලින් ඉතා ක්‍රමවත්ව සාදා ගත්හ."),
        q("මහනුවර යුගයේ විහාර සිතුවම් අතර අතිශය ජනප්‍රිය වූ 'වෙස්සන්තර ජාතකය' දෙගල්දොරුවේ හා බොහෝ විහාරවල ඇඳ ඇත්තේ ඇයි?", "දාන පාරමිතාව හා භක්ති හැඟීම් ජනතාවට දීමට", "රජුගේ යුද ජයග්‍රහණ වර්ණනා කිරීමට", "විදේශීය වෙළඳ ගනුදෙනු වාර්තා කිරීමට", "ලංකාවේ භූගෝලීය සිතියම පෙන්වීමට", "සාමාන්‍ය ජනතාවට බෞද්ධ සාරධර්ම දෘශ්‍ය කතා මගින් කියා දීම විහාර සිතුවම්වල මූලික අරමුණ විය."),
        q("මහනුවර යුගයේ 'වැසි වලාකුළු හා ජලය' සිතුවම්වල නිරූපණය කිරීමේදී ශිල්පියා භාවිත කළ සාම්ප්‍රදායික හැඩය කුමක්ද?", "රැලි සහිත වක්‍ර තීරු හා සමාන්තර ඉරි", "කැඩුණු ජ්‍යාමිතික කියුබ් කොටු රටාව", "සම්පූර්ණයෙන්ම බොඳ කළ ජල සායම් පැල්ලම්", "තියුණු කළු ත්‍රිකෝණාකාර කඩඉරි", "නොසැලෙන මත්ස්‍ය රූප හා වක්‍ර රැලි පටි මගින් ජලය සංකේතාත්මකව ඇඳීම මහනුවර ලක්ෂණයකි."),
        q("මහනුවර යුගයේ 'සූවිසි විවරණය' සහ 'සත් සතිය' වැනි සිතුවම්වල ප්‍රධාන වශයෙන් අවධාරණය වන සංයුති ගුණය කුමක්ද?", "සමමිතික රිද්මය හා ක්‍රමානුකූල පුනරාවර්තනය", "අසමමිතික වියුක්ත කැළඹිලි ස්වභාවය", "ගැඹුරු ඒකලක්ෂ්‍ය රේඛීය දෘෂ්ටිකෝණය", "කළු-සුදු එළිය අඳුර (Chiaroscuro) මැවීම", "එකම පෙළට සමාන ඉරියව්වෙන් බුදු රූප පිහිටුවීමෙන් දැඩි රිද්මයක් හා ආගමික ගෞරවයක් උපදී."),
        q("මහනුවර යුගයේ 'මුල් සම්ප්‍රදායික කලා ශිල්පීන්' අයත් වූ සංවිධානාත්මක ශ්‍රේණිය හඳුන්වනු ලැබුවේ කුමන නමින්ද?", "නවන්දන්න හෙවත් සිත්තර පරම්පරාව (පට්ටල් හතර)", "ගොවිගම වෙළඳ සංගමය", "සීගිරි භික්ෂු සංවිධානය", "බ්‍රිතාන්‍ය රාජකීය කලා ඇකඩමිය", "රජුගේ ආභරණ, දැව, කැටයම් හා සිතුවම් කර්මාන්ත පාරම්පරික ගුරුකුල මගින් පවත්වාගෙන යන ලදී."),
        q("දඹුල්ල හා දෙගල්දොරුව සිතුවම්වල සඳ හා හිරු සංකේතවත් කර ඇති ආකාරය කුමක්ද?", "මුහුණක් සහිත සුදු හා රන්වන් වෘත්ත ලෙස", "දම් පැහැති කුරුස හැඩැති තරු ලෙස", "හතරැස් කොටු තුළ ඇඳි ගිනිදැල් ලෙස", "රේඛා නොමැතිව හිස් අවකාශය ලෙස", "චරිත ආරෝපණය කරමින් ඉර හඳ පවා මිනිස් මුහුණු හා රශ්මි රේඛා සහිතව ඇඳීම දේශීය ක්‍රමයයි."),
        q("මහනුවර යුගයේ 'වියන් සිතුවම්' (Ceiling Paintings) ප්‍රධාන වශයෙන් නිරූපණය කර ඇත්තේ කුමන විහාරයකද?", "කැලණිය හා දඹුල්ල විහාර ලෙන් සිවිලිමේ", "අනුරාධපුර සමාධි පිළිම මළුවේ", "පොළොන්නරු ශිව දේවාල අංක 2 හි", "කතරගම කිරිවෙහෙර පිටත ගර්භයේ", "ලෙන් පියස්සේ හා ලී සිවිලිම්වල රෙදි වියන් (Canopy) හා නෙළුම් මල් මණ්ඩල සිතුවම් කිරීම සුලබ විය."),
        q("මහනුවර යුගයේ 'බුද්ධ චරිතයට අමතරව' සමාජ ඉතිහාසය හැදෑරීමට උපකාරී වන අංග බිතුසිතුවම්වල පෙනෙන්නේ කෙසේද?", "එවකට පැවති ඇඳුම්, ගෙවල් හා ආභරණ ඇඳීමෙන්", "පුවත්පත් වාර්තා බිත්තිවල ඇලවීමෙන්", "විදේශීය ඡායාරූප ශිල්පීන්ගේ රූප ඇඳීමෙන්", "සංඛ්‍යාත්මක ජනගහන වගු ලියා තැබීමෙන්", "ජාතක කතා චරිතවලට පවා 18 වන සියවසේ උඩරට නිලමේ ඇඳුම් හා පැලැස්තර ඇන්දවීම සිදු විය."),
        q("මහනුවර සිතුවම්වල 'රජු හෝ ප්‍රභූවරයෙකු' ඇඳීමේදී පැළඳ සිටින විශේෂිත ශීර්ෂාභරණය කුමක්ද?", "හතර මුළු තොප්පිය හෙවත් නිලමේ හිස්වැසුම", "ග්‍රීක රන්වන් ඔලිව් අතු ඔටුන්න", "යුරෝපීය යකඩ හෙල්මටය", "චීන උණ බට වටකුරු තොප්පිය", "උඩරට රාජ සභාවේ සම්ප්‍රදායික ඇඳුම් ආයිත්තම් විහාර සිතුවම් තුළ සජීවීව සටහන් වී ඇත."),
        q("කුණ්ඩසාලේ, රිදී විහාරය හා ලෙව්කේ වලව්ව වැනි මහනුවර යුගයේ නිර්මාණවල 'දොර උළුවහු' අලංකාර කළේ කුමන ලෝහ අංගවලින්ද?", "කැටයම් කළ පිත්තල අගුල් හා කොකු", "මල නොබැඳෙන වානේ ඉස්කුරුප්පු ඇණ", "ප්ලාස්ටික් හා රබර් අල්ලු", "රෝම සිමෙන්ති පුවරු", "උළුවහු අල්ලු, අගුල් තහඩු (මල් අගුල්) හා පිත්තල සරනේරු පවා සියුම් කැටයමින් නිමවීය."),
        q("මහනුවර යුගයේ 'බිතුසිතුවම් සම්ප්‍රදායේ' පසුබෑම හා වෙනස් වීම සිදු වූයේ කුමන කාලපරිච්ඡේදයේදීද?", "19 වන සියවසේ බ්‍රිතාන්‍ය පාලන යුගයේදී", "12 වන සියවසේ පොළොන්නරු යුගයේදී", "ක්‍රි.පූ. 3 වන සියවසේ මහින්දාගමනයේදී", "14 වන සියවසේ ගම්පොළ යුගයේදී", "බ්‍රිතාන්‍ය යටත් විජිතකරණයත් සමඟ යුරෝපීය දෘෂ්ටිකෝණ හා කෘත්‍රිම තීන්ත විහාරවලට පිවිසියේය."),
        q("සම්ප්‍රදායික මහනුවර ශෛලිය හා බටහිර ශෛලිය මුසු කරමින් නව පණක් දුන් 20 වන සියවසේ 'කැලණි විහාර' චිත්‍ර ශිල්පියා කවුරුන්ද?", "සෝලියස් මෙන්ඩිස් මහතා", "ජෝර්ජ් කීට් මහතා", "දෙවරගම්පල සිල්වත්තැන", "අයිවන් පීරිස් මහතා", "අජන්තා හා සීගිරි ආභාසය ලබමින් දේශීය කලා අනන්‍යතාවක් ඇති කිරීමට සෝලියස් මෙන්ඩිස් සමත් විය."),
        q("අ.පො.ස. සාමාන්‍ය පෙළ චිත්‍ර කලා සිසුවෙකුට 'මහනුවර යුගයේ සිතුවම් හා මෝස්තර' හැදෑරීමෙන් ලැබෙන ප්‍රධානම අගය කුමක්ද?", "දේශීය සැරසිලි රිද්මය හා කතා ඉදිරිපත් කිරීම", "ත්‍රිලක්ෂ්‍ය දෘෂ්ටිකෝණය මැන ඇඳීම", "ඩිජිටල් ත්‍රිමාණ සජීවීකරණ මෘදුකාංග භාවිතය", "ඇක්‍රිලික් වියුක්ත පැල්ලම් නිර්මාණය", "නිර්මාණශීලී මෝස්තර රටා, සංකේතාත්මක වර්ණ හා අඛණ්ඩ කතා කීමේ රීතිය සාමාන්‍ය පෙළ ප්‍රායෝගික අංශයටද වැදගත්ය.")
    )
}
